const p={getName(){return"foxnews"},async getTab(){const[t]=await chrome.tabs.query({active:!0,currentWindow:!0});return t},async getHTML(){const t=await this.getTab();return console.log(t),(await chrome.scripting.executeScript({target:{tabId:t.id},func:()=>document.documentElement.outerHTML}))[0].result},async getPostAuthor(){const t=await this.getHTML();let e="";return e=$(t).find("div.author-byline").clone().find(".article-source").remove().end().text(),e=e.replace("By",""),e.trim()},async getPostTitle(){const t=await this.getHTML();return $(t).find("h1.headline").first().text().trim()},async getPostContent(){const t=await this.getHTML();let e="";const n=await this.getUrlResource();if(console.log(`resource : ${n}`),n!=="live-news")$(t).find("div.article-body").find("p").each((s,i)=>{let r=$(i).text();e+=`<p>${r}</p>`});else{let i=`<p>${$(t).find("div.liveblog-content").find("div.sidebar-content").first().find(".title").text()}</p>`,r="";$(t).find("div.liveblog-content").find("div.sidebar-content").first().find("div.content li").each((c,o)=>{let l=$(o).text();r+=`<p>${l}</p>`});let a="";$(t).find("div.main-content div.article-items article").each((c,o)=>{let l=$(o).find(".title").text();a+=`<h2>${l}</h2>`,$(o).find("div.article-item-content div.article-item-body p").each((h,d)=>{let u=$(d).text();a+=`<p>${u}</p>`})}),e=i+r+a}return e},async getUrlResource(){const t=await this.getTab();return new URL(t.url).pathname.split("/").filter(Boolean)[0]},async getPageContent(){return{author:await this.getPostAuthor(),title:await this.getPostTitle(),postContent:await this.getPostContent()}},async generateContentHTML(t){const e=t.author,n=t.title,s=t.postContent;let i=`<p class="fs-2">${n}</p>`;return i+=`<p class="fs-5 fw-bold">By: ${e}</p>`,i+=`<p class="fs-6 ttsoc-read-more">${s}</p>`,i},buildSelectedContent(t,e=[]){let n={};if(t===void 0)return;const s=$("<div>").html(t.postContent).text();return n.postContent=s,n.title=t.title,n.author=t.author,n}};export{p as default};
